globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, figures, optionFigures, steps, context, audio, numericAnswer} = row;
    const condition = figures?.length ? {items: figures} : figure;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(condition || optionFigures ? {choiceLayout: {condition, options},
        choiceImages: options.map(option => option.image),
        ...(condition?.src ? {conditionImage: condition.src, conditionAlt: condition.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + 1), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

const edition = globalThis.makeSubjectEdition({"subject":"chip","year":2013,"grade":"7-8","contest":"Человек и природа","letters":"АБВГД","points":3,"count":30,"language":"ru","tasksFile":"7-8_2013.pdf","answersFile":"reviewed-7-8.pdf","solutionsFile":"7-8kom2013.pdf","title":"Круговорот","reviewedKey":true}, [{"number":1,"question":"Первую русскую кругосветную экспедицию возглавлял","choices":["Беллинсгаузен","Дрейк","Кавендиш","Коцебу","Крузенштерн"],"answer":4,"points":3,"title":"Капитаны кругосветки","steps":["Первая русская кругосветная экспедиция вышла в море в 1803 году. «Надеждой» командовал Иван Крузенштерн, «Невой» — Юрий Лисянский.","Общее руководство принадлежало Крузенштерну. Беллинсгаузен возглавил более позднюю экспедицию к Антарктиде."]},{"number":2,"question":"Какую долю всех запасов воды Земли приблизительно составляет вода атмосферы?","choices":["около 0,001 %","примерно 0,1 %","около 4 %","примерно 10 %","около 25%"],"answer":0,"points":3,"title":"Вода над Землёй","steps":["Сравним запас воды в атмосфере, около 13 тысяч км³, со всеми запасами воды Земли, около 1,4 миллиарда км³.","Деление даёт примерно одну стотысячную общего объёма. Чтобы выразить долю в процентах, умножаем на 100 и получаем около 0,001 %."]},{"number":3,"question":"На картине Яна Матейко изображён знаменитый учёный, создавший гелиоцентрическую модель Вселенной","choices":["Тихо Браге","Иоганн Кеплер","Николай Коперник","Михаил Васильевич Ломоносов","Парацельс"],"answer":2,"points":3,"title":"Астроном на полотне","steps":["Модель, в которой Земля и другие планеты обращаются вокруг Солнца, называют гелиоцентрической. Её изложил астроном из Торуни в книге 1543 года.","Ян Матейко изобразил Николая Коперника. Кеплер позднее уточнил форму орбит планет."],"figure":{"src":"assets/chip/2013/7-8-03.webp","detailSrc":"assets/chip/2013/detail/7-8-03.webp","width":480,"height":345,"alt":"Астроном наблюдает ночное небо среди своих инструментов."}},{"number":4,"question":"В романсе на слова Александра Сергеевича Пушкина есть строки: «Ночной зефир струит эфир». В них эфир — это","choices":["трансляция телевизионного сигнала в реальном времени","тихие звуки арфы","органическое соединение","гипотетическая всепроникающая среда","воздух, которым дышат боги"],"answer":4,"points":3,"title":"Поэтический эфир","steps":["В пушкинской строке ветерок заставляет струиться окружающий воздух. В античной традиции эфиром называли светлый верхний воздух, которым дышат боги.","Это поэтическое значение. Физики и химики тоже употребляли слово «эфир», но их термины возникли в другом контексте."]},{"number":5,"question":"Это растение зацветает раньше других.","choices":["","","","",""],"answer":1,"points":3,"title":"Первые после снега","steps":["Сравни время цветения в средней полосе. Одно из этих растений раскрывает жёлтые соцветия на чешуйчатых стеблях ещё до появления крупных листьев.","Это мать-и-мачеха. Купальница, нивяник, цикорий и колокольчик обычно распускаются позже."],"optionFigures":[{"src":"assets/chip/2013/7-8-05-a.webp","detailSrc":"assets/chip/2013/detail/7-8-05-a.webp","width":480,"height":267,"alt":"Оранжевый округлый цветок."},{"src":"assets/chip/2013/7-8-05-b.webp","detailSrc":"assets/chip/2013/detail/7-8-05-b.webp","width":480,"height":293,"alt":"Жёлтые корзинки на коротких стеблях."},{"src":"assets/chip/2013/7-8-05-c.webp","detailSrc":"assets/chip/2013/detail/7-8-05-c.webp","width":480,"height":320,"alt":"Корзинка с белыми краевыми цветками."},{"src":"assets/chip/2013/7-8-05-d.webp","detailSrc":"assets/chip/2013/detail/7-8-05-d.webp","width":480,"height":380,"alt":"Голубые цветки на ветвящемся стебле."},{"src":"assets/chip/2013/7-8-05-e.webp","detailSrc":"assets/chip/2013/detail/7-8-05-e.webp","width":480,"height":320,"alt":"Фиолетовый колокольчатый венчик."}]},{"number":6,"question":"Какой из перечисленных металлов в обычных условиях земной поверхности встречается только в составе соединений?","choices":["медь","платина","серебро","кальций","ртуть"],"answer":3,"points":3,"title":"Металл в самородке","steps":["Активные металлы на поверхности Земли обычно встречаются в составе соединений. Серебро, медь и платина известны в самородном виде, встречается и природная металлическая ртуть.","Кальций в обычных земных породах связан с другими элементами, например в известняке. Поэтому выбираем его."]},{"number":7,"question":"Эта горная система сформировалась 200 – 350 миллионов лет назад в эпоху становления суперконтинента Пангея:","choices":["Альпы","Гималаи","Кавказ","Кордильеры","Урал"],"answer":4,"points":3,"title":"Горы времён Пангеи","steps":["Альпы и Гималаи приобрели современный горный рельеф гораздо позже палеозоя. Нужна горная система, выросшая при столкновении древних континентов в конце палеозоя.","Это Урал. Уральские горы формировались при сближении Восточно-Европейской и соседних континентальных областей."]},{"number":8,"question":"Какое из перечисленных хранилищ вблизи поверхности Земли содержит наибольшее количество углерода?","choices":["в воде","в атмосфере","в растительных и животных организмах","в горючих полезных ископаемых","в карбонатных горных породах"],"answer":4,"points":3,"title":"Где хранится углерод","steps":["Учитываем долговременные запасы в земной коре. В каждом слое известняка или доломита углерод входит в состав карбонатов.","Среди перечисленных хранилищ крупнейшее — карбонатные породы. Быстрый обмен углеродом в воздухе и воде не делает их крупнейшими запасами."]},{"number":9,"question":"Продуценты — это организмы, которые","choices":["потребляют готовое органическое вещество","производят электрическую энергию","расщепляют органическое вещество до неорганического","создают органическое вещество из неорганического","находятся в стадии покоя и не питаются"],"answer":3,"points":3,"title":"Продуценты","steps":["В начале пищевой цепи нужны организмы, создающие органические вещества. Растения, например, используют углекислый газ и воду, получая энергию от света.","Таких производителей называют продуцентами. Потребители получают уже готовое органическое вещество."]},{"number":10,"question":"У какого паразита яйца проходят часть развития во внешней среде, вне тела хозяина и переносчика?","choices":["малярийный плазмодий","трипаносома","филярия","аскарида","боррелия (возбудитель болезни Лайма)"],"answer":3,"points":3,"title":"Стадия во внешней среде","steps":["Различаем промежуточного хозяина и внешнюю среду. Даже когда паразит находится в переносчике, он всё ещё находится в организме животного.","Яйца человеческой аскариды проходят часть развития в почве. Для этого этапа им не нужен другой живой хозяин."]},{"number":11,"question":"За эксперименты по исследованию новой аллотропной модификации углерода выпускникам МФТИ А. К. Гейму и К. С. Новосёлову в 2010 году была присуждена Нобелевская премия по физике. Этот двумерный материал называется","choices":["карбин","графин","графен","карбид","графит"],"answer":2,"points":4,"title":"Углерод в один слой","steps":["В графите атомы углерода образуют слои с шестиугольной решёткой. Один такой слой толщиной в атом представляет собой самостоятельный материал.","Это графен. Именно опыты с двумерным графеном принесли Гейму и Новосёлову Нобелевскую премию 2010 года."],"figure":{"src":"assets/chip/2013/7-8-11.webp","detailSrc":"assets/chip/2013/detail/7-8-11.svg","width":480,"height":393,"alt":"Один слой атомов, соединённых в шестиугольную решётку."}},{"number":12,"question":"Какой из перечисленных материков подходит для наблюдения эффекта Новой Земли во время полярной ночи?","choices":["Австралии","Антарктиде","Африке","Южной Америке","Индостане"],"answer":1,"points":4,"title":"Полярный мираж","steps":["Слои воздуха разной температуры преломляют свет. При сильной температурной инверсии лучи от Солнца, ещё находящегося за горизонтом, могут дойти до наблюдателя.","Условия такого полярного миража бывают в Антарктиде. Название «эффект Новой Земли» происходит от другого места, где его наблюдали."]},{"number":13,"question":"Сколько времени в природе может сохраняться прочный полиэтиленовый пакет, в том числе в виде мелких фрагментов?","choices":["менее 1 месяца","около 1 года","от 5 до 10 лет","от 20 до 50 лет","более 100 лет"],"answer":4,"points":4,"title":"Пакет в лесу","steps":["Полиэтилен очень устойчив. Разрыв пакета на мелкие фрагменты ещё не означает, что сам полимер полностью разложился.","Для обычного прочного пакета возможен срок свыше столетия. Конкретное время зависит от света, температуры и других условий."]},{"number":14,"question":"С чем связано сезонное снижение солёности прибрежных поверхностных вод Андаманского моря летом и в начале осени?","choices":["с пассатами","с юго-западными муссонами","со смещением течения Агульяс","с наступлением Эль-Ниньо","со строительством ирригационных сооружений на реках, впадающих в море"],"answer":1,"points":4,"title":"Сезон в Андаманском море","steps":["Летом юго-западный муссон приносит обильные осадки. Осадки и усилившийся речной сток добавляют пресную воду, особенно у устьев рек.","Поэтому поверхностная прибрежная вода становится менее солёной. Вариант про юго-западные муссоны объясняет сезонность."]},{"number":15,"question":"Какая из этих планет вращается вокруг своей оси с востока на запад?","choices":["","","","",""],"answer":1,"points":4,"title":"Вращение планет","steps":["Земля и большинство планет вращаются с запада на восток. У Венеры осевое вращение направлено в противоположную сторону.","Ищи покрытую сплошными облаками Венеру. Полосатый Юпитер и окольцованный Сатурн вращаются в обычном направлении."],"adaptation":"Ключ сверен с изображениями планет.","optionFigures":[{"src":"assets/chip/2013/7-8-15-a.webp","detailSrc":"assets/chip/2013/detail/7-8-15-a.webp","width":480,"height":480,"alt":"Голубая планета с океанами и материками."},{"src":"assets/chip/2013/7-8-15-b.webp","detailSrc":"assets/chip/2013/detail/7-8-15-b.webp","width":480,"height":480,"alt":"Планета со сплошной светлой облачностью."},{"src":"assets/chip/2013/7-8-15-c.webp","detailSrc":"assets/chip/2013/detail/7-8-15-c.webp","width":432,"height":480,"alt":"Газовая планета с крупными видимыми кольцами."},{"src":"assets/chip/2013/7-8-15-d.webp","detailSrc":"assets/chip/2013/detail/7-8-15-d.webp","width":384,"height":480,"alt":"Полосатый газовый гигант."},{"src":"assets/chip/2013/7-8-15-e.webp","detailSrc":"assets/chip/2013/detail/7-8-15-e.webp","width":480,"height":480,"alt":"Красноватая планета с тёмными областями."}]},{"number":16,"question":"На побережье Чёрного моря, в районе Новороссийска, суда и прибрежные строения зимой иногда покрываются льдом. Это происходит из-за","choices":["подъёма сероводорода с больших глубин моря","резкого ветра с моря","высокой влажности воздуха","высокого атмосферного давления","сильного ветра с гор"],"answer":4,"points":4,"title":"Ледяной ветер","steps":["У Новороссийска холодный воздух за горным хребтом может стремительно спускаться к побережью. Такой ветер называют борой.","Поднятые ветром брызги замерзают на холодных конструкциях и судах. Значит, причина — сильный холодный ветер с гор."]},{"number":17,"question":"Каков средний период цикла солнечной активности, который определяют по изменениям числа солнечных пятен?","choices":["7 лет","11 лет","17 лет","21 год","47 лет"],"answer":1,"points":4,"title":"Ритм солнечных пятен","steps":["Наблюдатели подсчитывают пятна на Солнце. Между последовательными максимумами их числа проходит неодинаковый промежуток, но у него есть устойчивое среднее значение.","Обычная продолжительность цикла — около 11 лет. Это период изменения активности Солнца."],"adaptation":"Убрано недоказанное обобщение о влиянии на исторические события."},{"number":18,"question":"Поговорка «Вот тебе, бабушка, и Юрьев день!» напоминает","choices":["об отмене празднования старого Нового года","о полном запрете перехода крестьян от одного помещика к другому","о начале нового финансового года","о начале княжения Юрия Долгорукого","о полном запрете передела крестьянской земли"],"answer":1,"points":4,"title":"Юрьев день","steps":["В Московском государстве крестьянин при определённых условиях мог сменить землевладельца в дни около осеннего Юрьева дня.","Ограничение, а затем запрет переходов лишили крестьян ожидаемого права. Отсюда выражение о несбывшемся ожидании."]},{"number":19,"question":"На этом рисунке учёный при помощи маятника демонстрирует опыт, подтверждающий","choices":["суточное вращение Земли","отклонение магнитного полюса от географического","возникновение электромагнитных колебаний","вращение Земли вокруг Солнца","вращение Луны вокруг Земли"],"answer":0,"points":4,"title":"Маятник Фуко","steps":["У длинного свободно колеблющегося маятника направление колебаний стремится сохраняться относительно инерциальной системы. Подвесившая его Земля поворачивается.","Наблюдателю на полу кажется, что плоскость колебаний постепенно разворачивается. Так опыт демонстрирует суточное вращение Земли."],"figure":{"src":"assets/chip/2013/7-8-19.webp","detailSrc":"assets/chip/2013/detail/7-8-19.webp","width":480,"height":356,"alt":"Публичная демонстрация с подвешенным под куполом маятником."}},{"number":20,"question":"Космонавты в космической станции, вращающейся на орбите около Земли, испытывают невесомость. Это значит:","choices":["на них не действуют никакие силы","они не испытывают притяжение Земли","на них действует только одна существенная сила – притяжение Земли","притяжение Луны компенсирует притяжение Земли","на космической станции нет невесомости"],"answer":2,"points":4,"title":"Невесомость на орбите","steps":["Притяжение Земли сохраняется и на высоте станции. Именно оно искривляет путь корабля и позволяет ему оставаться на орбите.","Станция и космонавт свободно падают вместе, поэтому опора почти не давит на человека. Это и есть состояние невесомости."]},{"number":21,"question":"Какова разница между средним годом юлианского календаря (365,25 суток) и тропическим годом (около 365,2422 суток)?","choices":["1 месяц","1 сутки","около 0,0078 суток","0,242 суток","её нет"],"answer":2,"points":5,"title":"Ошибка календаря","steps":["В юлианском календаре за четыре года получается 1461 день. Средний год составляет 1461 ÷ 4 = 365,25 суток. Тропический год длится около 365,2422 суток.","Вычитаем и получаем около 0,0078 суток, то есть примерно 11 минут 14 секунд. Четверть суток — добавка к 365 дням, а не расхождение с природным годом."],"adaptation":"Исправлены определение тропического года и числовое значение в ответах."},{"number":22,"question":"Что известно о температуре разных межледниковий за последние два миллиона лет?","choices":["температуры разных межледниковий различались без строгого монотонного хода","каждое последующее оказывалось теплее предыдущего","средние температуры оставались неизменными","первые межледниковья были прохладными, затем более тёплыми, а потом снова прохладными","первые межледниковья были тёплыми, затем более холодными, а потом снова тёплыми (но прохладнее первых)"],"answer":0,"points":5,"title":"Межледниковья","steps":["Геологические записи показывают чередование холодных и сравнительно тёплых периодов. При этом температура в разные межледниковья зависела от многих причин.","Средние и максимальные температуры межледниковий различались. Строгой последовательности «каждый раз холоднее» для всего периода нет."],"adaptation":"Убран не подтверждаемый палеоклиматическими данными тезис о последовательном похолодании."},{"number":23,"question":"У всех насекомых в жизненном цикле всегда есть несколько линек. Какой гормон участвует в их регуляции?","choices":["глюкагон","дофамин","трийодтиронин","эстрадиол","ювенильный"],"answer":4,"points":5,"title":"Линьки насекомых","steps":["Линьку запускают экдистероиды. От уровня другого гормона зависит, сохранит ли насекомое после очередной линьки признаки личинки.","Это ювенильный гормон. Среди перечисленных вариантов он участвует в управлении превращением насекомого."]},{"number":24,"question":"Скотоводы гор юга Сибири и Монголии перегоняют стада овец летом вверх, на горные пастбища, а зимой спускаются с ними вниз, в сухие степи и полупустыни на предгорных равнинах, потому что","choices":["туда свозят сено, заготовленное на склонах гор","после стрижки овцам в горах холодно","овцы питаются сухой степной травой, оставшейся с лета","в высокогорьях зимой овцы страдают от недостатка кислорода","в горах зимой засыпает все дороги и связь с внешним миром обрывается"],"answer":2,"points":5,"title":"Зимнее пастбище","steps":["На высоком пастбище снег может скрыть корм. На сухих предгорных равнинах снега меньше, а с лета там остаётся высохшая трава.","Стадо может пастись и зимой. Именно доступность корма объясняет спуск в предгорья."]},{"number":25,"question":"Ранней весной в долинных лесах юга Дальнего Востока цветёт связноплодник (симплокарпус) почколистный. Кроме яркой окраски покрывала и неприятного запаха, насекомых-опылителей может привлекать","choices":["очень большое количество нектара","яркая окраска венчика","морфология соцветия","издаваемые соцветием звуки","повышенная температура соцветия"],"answer":4,"points":5,"title":"Тёплое соцветие","steps":["У ряда ароидных соцветие выделяет тепло. Ранней весной оно может быть заметно теплее, чем окружающий воздух.","Поэтому у симплокарпуса дополнительным привлекающим признаком служит повышенная температура соцветия."],"figure":{"src":"assets/chip/2013/7-8-25.webp","detailSrc":"assets/chip/2013/detail/7-8-25.webp","width":480,"height":480,"alt":"Округлое покрывало соцветия выступает над почвой."}},{"number":26,"question":"На государственном флаге и гербе Португалии изображён прибор, символизирующий её роль в эпоху великих географических открытий, — это","choices":["армиллярная сфера","гномон","компас","корабельный штурвал","секстант"],"answer":0,"points":5,"title":"Навигация на гербе","steps":["За португальским щитом видны пересекающиеся золотые кольца. Они обозначают важные окружности небесной сферы.","Так выглядит армиллярная сфера. Это старинная модель неба и символ эпохи португальских плаваний."]},{"number":27,"question":"У какой из этих птиц, гнездящейся на островах Южного океана, спутниковое слежение зафиксировало кругосветные перелёты вдоль поясов западных ветров?","choices":["","","","",""],"answer":0,"points":5,"title":"Кругосветный перелёт","steps":["Различай перелёт между полюсами и круговой маршрут по долготам. Нужна крупная морская птица, планирующая на длинных узких крыльях над Южным океаном.","Такие кругосветные маршруты зарегистрированы у сероголовых альбатросов. Крачки славятся прежде всего перелётами из Арктики в Антарктику."],"optionFigures":[{"src":"assets/chip/2013/7-8-27-a.webp","detailSrc":"assets/chip/2013/detail/7-8-27-a.webp","width":480,"height":320,"alt":"Морская птица с серой головой и мощным клювом."},{"src":"assets/chip/2013/7-8-27-b.webp","detailSrc":"assets/chip/2013/detail/7-8-27-b.webp","width":320,"height":480,"alt":"Длинноногая птица с красным клювом."},{"src":"assets/chip/2013/7-8-27-c.webp","detailSrc":"assets/chip/2013/detail/7-8-27-c.webp","width":480,"height":459,"alt":"Белая водоплавающая птица с длинной изогнутой шеей."},{"src":"assets/chip/2013/7-8-27-d.webp","detailSrc":"assets/chip/2013/detail/7-8-27-d.webp","width":480,"height":320,"alt":"Птица с большим клювом и горловым мешком."},{"src":"assets/chip/2013/7-8-27-e.webp","detailSrc":"assets/chip/2013/detail/7-8-27-e.webp","width":480,"height":320,"alt":"Небольшая морская птица с чёрной шапочкой и красным клювом."}]},{"number":28,"question":"Примем, что эритроцит прошёл заданный маршрут по малому и большому кругам кровообращения за 27 сердечных сокращений. Какое время это займёт при пульсе 75 ударов в минуту?","choices":["7 секунд","10 секунд","15–16 секунд","21–23 секунды","40–45 секунд"],"answer":3,"points":5,"title":"Сколько длится круг","steps":["Скорость крови и длина пути по сосудам различны, поэтому точного времени для любого эритроцита нет. В учебной задаче примем путь в 27 ударов сердца.","При пульсе 75 ударов в минуту один удар длится 60 ÷ 75 = 0,8 секунды. Умножаем 27 на 0,8 и получаем 21,6 секунды."],"adaptation":"Добавлены данные для расчёта: длительность зависит от маршрута и работы сердца."},{"number":29,"question":"Для получения обычного содово-известкового стекла песок спекают с содой и известняком. Какой из содержащихся в сырье элементов в итоге не попадает в состав стекла?","choices":["кремний","кислород","натрий","углерод","кальций"],"answer":3,"points":5,"title":"Из чего получается стекло","steps":["Песок даёт кремнезём, а сода и известняк — соединения натрия и кальция. При нагревании их карбонаты выделяют углекислый газ.","Углерод уходит с газом, тогда как кремний, натрий, кальций и кислород остаются в обычном силикатном стекле."]},{"number":30,"question":"На схемах О — оплодотворение, М — мейоз; толстая линия показывает диплоидную фазу, тонкая — гаплоидную. Выбери номера схем по порядку: мхи, папоротники, семенные растения, высшие животные.","choices":["1, 2, 3, 4","2, 3, 4, 1","4, 3, 1, 2","2, 1, 3, 4","1, 3, 2, 4"],"answer":3,"points":5,"title":"Два поколения","steps":["После оплодотворения образуется диплоидная клетка, после мейоза — гаплоидные. У мхов выражено гаплоидное поколение, у папоротников преобладает, но не вытесняет гаметофит, диплоидное.","У семенных гаметофит сильно уменьшен, у животных гаплоидны только гаметы. По порядку «мхи, папоротники, семенные, животные» схемы идут как 2, 1, 3, 4."],"figure":{"src":"assets/chip/2013/7-8-30.webp","detailSrc":"assets/chip/2013/detail/7-8-30.svg","width":480,"height":121,"alt":"Четыре пронумерованных цикла; одинарные и утолщённые дуги показывают доли двух фаз."}}]);
